<template><section><FieldsForm :value="value" :fields="fields" :disabled="disabled" @input="$emit('input',$event)"/><FileField :value="value.frontFileId" :receipt-key="receiptScope+':front'" purpose="CHANNEL" title="证件正面" images-only :disabled="disabled" @input="set('frontFileId',$event)" @preview="$emit('preview',$event)"/><FileField :value="value.backFileId" :receipt-key="receiptScope+':back'" purpose="CHANNEL" title="证件反面（护照除外）" images-only :disabled="disabled" @input="set('backFileId',$event)" @preview="$emit('preview',$event)"/></section></template>
<script>import FieldsForm from './FieldsForm';import FileField from './FileField';export default {components:{FieldsForm,FileField},props:{value:{type:Object,required:true},receiptScope:{type:String,required:true},disabled:Boolean},computed:{fields(){return [{key:'type',label:'证件类型',type:'select',required:true,options:[['MAINLAND_IDCARD','大陆身份证'],['OVERSEA_PASSPORT','护照'],['HONGKONG','港澳通行证（香港）'],['MACAO','港澳通行证（澳门）'],['TAIWAN','台湾居民通行证'],['FOREIGN_RESIDENT','外国人永久居留证'],['HONGKONG_MACAO_RESIDENT','港澳居民居住证'],['TAIWAN_RESIDENT','台湾居民居住证']].map(([value,label])=>({value,label}))},{key:'name',label:'证件姓名',required:true,max:100},{key:'number',label:'证件号码',max:32,help:'首次填写完整号码；已有受保护内容时留空保留。'},{key:'address',label:'证件地址',max:512,help:'已有受保护地址留空保留。'},{key:'validFrom',label:'有效期开始',required:true,placeholder:'YYYY-MM-DD'},{key:'longTerm',label:'长期有效',type:'boolean'},...(!this.value.longTerm?[{key:'validThrough',label:'有效期截止',required:true,placeholder:'YYYY-MM-DD'}]:[])];}},methods:{set(key,value){this.$emit('input',{...this.value,[key]:value});}}};</script>
